solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <string>
#include <vector>

struct Version { std::uint16_t major{ 0 }, minor{ 0 }, patch{ 0 }, build{ 0 }; };

bool parseVersion(const std::string& text, Version& out)
{
    std::string s{ text };
    if (!s.empty() && (s[0] == 'v' || s[0] == 'V')) s.erase(0, 1);
    std::vector<std::uint16_t> parts;
    std::string current;
    for (std::size_t i{ 0 }; i <= s.size(); ++i)
    {
        if (i == s.size() || s[i] == '.')
        {
            if (current.empty() || current.size() > 5) return false;
            const unsigned long v{ std::stoul(current) };
            if (v > 65535) return false;
            parts.push_back(static_cast<std::uint16_t>(v));
            current.clear();
            continue;
        }
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) return false;
        current += s[i];
    }
    if (parts.empty() || parts.size() > 4) return false;
    parts.resize(4, 0);
    out = { parts[0], parts[1], parts[2], parts[3] };
    return true;
}

std::string formatVersion(const Version& v, int parts)
{
    const std::uint16_t all[4]{ v.major, v.minor, v.patch, v.build };
    std::string s;
    for (int i{ 0 }; i < parts && i < 4; ++i) s += (i ? "." : "") + std::to_string(all[i]);
    return s;
}

void packVersion(const Version& v, std::uint32_t& ms, std::uint32_t& ls)
{
    ms = (static_cast<std::uint32_t>(v.major) << 16) | v.minor;
    ls = (static_cast<std::uint32_t>(v.patch) << 16) | v.build;
}

Version unpackVersion(std::uint32_t ms, std::uint32_t ls)
{
    return { static_cast<std::uint16_t>(ms >> 16), static_cast<std::uint16_t>(ms & 0xFFFF), static_cast<std::uint16_t>(ls >> 16), static_cast<std::uint16_t>(ls & 0xFFFF) };
}

int compareVersions(const Version& a, const Version& b)
{
    std::uint32_t ams, als, bms, bls;
    packVersion(a, ams, als);
    packVersion(b, bms, bls);
    const std::uint64_t x{ (static_cast<std::uint64_t>(ams) << 32) | als }, y{ (static_cast<std::uint64_t>(bms) << 32) | bls };
    return x < y ? -1 : x > y ? 1 : 0;
}

bool updateAvailable(const std::string& running, const std::string& latest)
{
    Version r, l;
    return parseVersion(running, r) && parseVersion(latest, l) && compareVersions(l, r) > 0;
}

unitTests:
TEST("parsing") {
    Version v; CHECK(parseVersion("1.2.3.4", v)); CHECK_EQ(int(v.major), 1); CHECK_EQ(int(v.build), 4);
    CHECK(parseVersion("v2.10", v)); CHECK_EQ(int(v.minor), 10); CHECK_EQ(int(v.patch), 0); CHECK(parseVersion("65535", v)); CHECK_EQ(int(v.major), 65535);
    CHECK(!parseVersion("", v)); CHECK(!parseVersion("1..2", v)); CHECK(!parseVersion("1.2.3.4.5", v)); CHECK(!parseVersion("1.2b", v)); CHECK(!parseVersion("65536", v)); CHECK(!parseVersion(" 1.2", v)); CHECK(!parseVersion("1.", v));
}
TEST("formatting and packing") {
    Version v; parseVersion("1.2", v); CHECK_EQ(formatVersion(v, 3), std::string("1.2.0")); CHECK_EQ(formatVersion(v, 4), std::string("1.2.0.0"));
    std::uint32_t ms, ls; parseVersion("2.0.10.300", v); packVersion(v, ms, ls); CHECK_EQ(ms, 0x00020000u); CHECK_EQ(ls, 0x000A012Cu);
    CHECK_EQ(formatVersion(unpackVersion(ms, ls), 4), std::string("2.0.10.300"));
}
TEST("comparing") {
    Version a, b; parseVersion("2.0.10", a); parseVersion("2.0.9", b); CHECK_EQ(compareVersions(a, b), 1); CHECK_EQ(compareVersions(b, a), -1);
    parseVersion("2.0.10.0", b); CHECK_EQ(compareVersions(a, b), 0);
    CHECK(updateAvailable("2.0.2", "2.0.10")); CHECK(!updateAvailable("2.0.10", "2.0.2")); CHECK(!updateAvailable("2.0.2", "2.0.2.0")); CHECK(!updateAvailable("2.0.2", "latest"));
}

